 let ignored=records.reads.formals.iter().find(|row|matches!(data.flow.formals.get(row.formal),Some(normalized::entities::ParameterEntity::Source{declaration})if text(&f,*declaration)=="ignored")&&owner_text(row.owner).starts_with("def unused(")).unwrap();assert_eq!(ignored.status,ReadAssessment::CompleteNoReadUnderModel,"{ignored:?}");
 let value=records.reads.formals.iter().find(|row|matches!(data.flow.formals.get(row.formal),Some(normalized::entities::ParameterEntity::Source{declaration})if text(&f,*declaration)=="value")&&owner_text(row.owner).starts_with("def unused(")).unwrap();assert_eq!(value.status,ReadAssessment::ObservedRead);
 assert!(records.reads.reads.iter().any(|r|r.location==ReadLocation::DeclaredGlobal));
